struct Product { std::string name; int count; double price; double finalPrice; }; std::vector<Product> bill; double multiplicate(double x, double y) { return x * y; } void manageProducts() { std::string name, count, price; std::cout << "Type ':q' to end section.\n"; while (true) { std::cout << "Enter the name for the product.\n"; std::getline(std::cin, name); if (name == ":q" || name == ":Q") { std::cout << "Job terminating...\n"; std::this_thread::sleep_for(std::chrono::seconds(1)); break; } std::cout << "Enter the count of " << name << ".\n"; std::cin >> count; std::cin.ignore(); std::cout << "Enter the price of " << name << " as USD.\n"; std::cin >> price; std::cin.ignore(); Product newProduct{name, std::stoi(count), std::stod(price), multiplicate(std::stod(price), std::stoi(count))}; bill.push_back(newProduct); } } void createBill() { std::ofstream file("bill.txt", std::ios::app); double totalPrice_ofAll = 0.0; for (const auto& p : bill) { file << "Product name: " << p.name << ".\nProduct count: " << p.count << ".\nProduct price as USD: " << p.price << ".\nTotal price of the product: " << p.finalPrice << ".\n\n================================================\n"; totalPrice_ofAll += p.finalPrice; } auto now = std::chrono::system_clock::now(); std::time_t now_time_t = std::chrono::system_clock::to_time_t(now); std::tm* local_Time = std::localtime(&now_time_t); file << "Sales ended.\nTotal amount of all as USD: " << totalPrice_ofAll << ".\nBill save time: " << std::put_time(local_Time, "%Y-%m-%d %H:%M:%S") << "\n================================================\n\n"; } int main() { manageProducts(); std::this_thread::sleep_for(std::chrono::milliseconds(500)); createBill(); ::system("clear"); std::cout << "Click 'enter' to exit.\n"; std::cin.get(); return 0; }
